const es = new EventSource("/api/builds/42/events", { withCredentials: true });

es.addEventListener("progress", (e) => {
  render(JSON.parse(e.data));          // e.lastEventId — значение поля id этого события
});
es.onerror = () => {
  // 0 = CONNECTING: браузер сам переподключается и сам пошлёт Last-Event-ID
  // 2 = CLOSED: сервер ответил 204 или не text/event-stream, реконнекта не будет
  console.log(es.readyState);
};
// Сервер один раз пишет "retry: 3000\n" (пауза перед реконнектом, мс)
// и в каждом событии "id: <n>\n".

// SSE parser as a TransformStream: strings in, {event, data, id, lastEventId} out.
// Implements the WHATWG event stream rules: comment lines, field: value,
// several data lines joined with \n, id / event / retry fields, blank line dispatches.
function sseParser() {
  let buf = "";
  let lastEventId = "";
  let data = [], event = "", id;       // fields of the event being assembled
  const reset = () => { data = []; event = ""; id = undefined; };

  const handleLine = (line, controller) => {
    if (line === "") {                                   // blank line: dispatch
      if (id !== undefined) lastEventId = id;
      if (data.length) controller.enqueue({ event: event || "message", data: data.join("\n"), id, lastEventId });
      return reset();
    }
    if (line.startsWith(":")) return;                    // comment / keep-alive, ignore
    const colon = line.indexOf(":");
    const field = colon === -1 ? line : line.slice(0, colon);
    let value = colon === -1 ? "" : line.slice(colon + 1);
    if (value.startsWith(" ")) value = value.slice(1);   // exactly one space is dropped
    if (field === "data") data.push(value);
    else if (field === "event") event = value;
    else if (field === "id" && !value.includes("\0")) id = value;
    // "retry" and unknown fields: ignored by this client
  };

  return new TransformStream({
    transform(text, controller) {
      buf += text;
      let tail = "";
      if (buf.endsWith("\r")) { tail = "\r"; buf = buf.slice(0, -1); }   // \r may be followed by \n in the next chunk
      buf = buf.replace(/\r\n|\r/g, "\n");                              // CRLF and CR become LF
      let nl;
      while ((nl = buf.indexOf("\n")) !== -1) {
        handleLine(buf.slice(0, nl), controller);
        buf = buf.slice(nl + 1);
      }
      buf += tail;
    },
    flush(controller) {
      if (buf) handleLine(buf.replace(/\r/g, "\n"), controller);       // a last line without \n
      // an event without a final blank line is never dispatched, per spec
    },
  });
}

// Reads an SSE response body: bytes -> text (TextDecoderStream keeps split
// multi-byte characters) -> events. Calls onEvent for every complete event.
async function readSSE(body, onEvent) {
  const events = body.pipeThrough(new TextDecoderStream()).pipeThrough(sseParser());
  const reader = events.getReader();
  let lastEventId = "";
  for (;;) {
    const { value, done } = await reader.read();
    if (done) return lastEventId;
    lastEventId = value.lastEventId;
    onEvent(value);
  }
}

